import { describe, it, expect, vi, beforeEach } from "vitest";
import { createActionScanner, validateActionShape, parseNavPath, createRateCap } from "./actions";
import type { Action } from "@shared/types";

// Seam 1 (agreed): the client action scanner — token stream in,
// cleaned prose + validated actions out. PLAN.md §3.4 / tickets 04, 06, 07.

function scan(chunks: string[]) {
  const scanner = createActionScanner();
  const actions: Action[] = [];
  let prose = "";
  for (const c of chunks) {
    const out = scanner.feed(c);
    actions.push(...out.actions);
    prose += out.prose;
  }
  const fin = scanner.flush();
  actions.push(...fin.actions);
  prose += fin.prose;
  return { prose, actions };
}

beforeEach(() => vi.spyOn(console, "warn").mockImplementation(() => {}));

describe("action scanner — prose passthrough", () => {
  it("passes plain text through untouched", () => {
    expect(scan(["Hello ", "world"]).prose).toBe("Hello world");
  });

  it("passes ordinary code fences through as prose (never executes)", () => {
    const { prose, actions } = scan([
      "Look:\n\n```js\nconsole.log(1)\n```\n\nAnd:\n\n```json\n{\"action\":\"navigate\"}\n```\n",
    ]);
    expect(actions).toEqual([]);
    expect(prose).toContain("```js");
    expect(prose).toContain("```json");
  });

  it("does not execute a JSON-ACTION fence (case-sensitive tag)", () => {
    const { actions } = scan(["```JSON-ACTION\n{\"action\":\"navigate\",\"path\":\"/x\"}\n```\n"]);
    expect(actions).toEqual([]);
  });
});

describe("action scanner — extraction", () => {
  it("extracts an action and strips it from the prose", () => {
    const { prose, actions } = scan([
      "Let me take you there.\n\n```json-action\n",
      '{"action":"scrollTo","sectionId":"pricing"}',
      "\n```\n\nEnjoy!",
    ]);
    expect(prose).toBe("Let me take you there.\n\n\nEnjoy!");
    expect(actions).toEqual([{ action: "scrollTo", sectionId: "pricing" }]);
  });

  it("extracts multiple actions in document order", () => {
    const { actions } = scan([
      "```json-action\n{\"action\":\"highlight\",\"selector\":\"#plans\"}\n```\n",
      "text between\n",
      "```json-action\n{\"action\":\"move\",\"near\":\"pricing\"}\n```\n",
    ]);
    expect(actions.map((a) => a.action)).toEqual(["highlight", "move"]);
  });

  it("holds prose after an opening fence until the fence closes (safe prefix mid-stream)", () => {
    const scanner = createActionScanner();
    const a = scanner.feed("before\n```json-action\n"); // nothing more yet
    expect(a.prose).toBe("before\n");
    expect(a.actions).toEqual([]);
    const b = scanner.feed('{"action":"move","near":"top-left"}\n```\nafter');
    expect(b.prose).toBe("\nafter");
    expect(b.actions).toEqual([{ action: "move", near: "top-left" }]);
  });

  it("handles a fence split across arbitrary token boundaries", () => {
    const text = "```json-action\n{\"action\":\"navigate\",\"path\":\"/about\"}\n```\n";
    const { actions } = scan(text.split("")); // one char per token
    expect(actions).toEqual([{ action: "navigate", path: "/about" }]);
  });

  it("discards invalid JSON in an action fence (+warn) and keeps it out of prose", () => {
    const { prose, actions } = scan(["```json-action\n{not json\n```\nvisible"]);
    expect(actions).toEqual([]);
    expect(prose).toBe("visible");
    expect(console.warn).toHaveBeenCalled();
  });

  it("discards an unclosed fence at end of stream (+warn)", () => {
    const { prose, actions } = scan(["ok\n```json-action\n{\"action\":\"move\",\"near\":\"x\"}"]);
    expect(actions).toEqual([]);
    expect(prose).toBe("ok\n");
    expect(console.warn).toHaveBeenCalled();
  });

  it("emits parsed-but-unknown action shapes for the executor to reject", () => {
    // scanner parses known-allowlist actions only; unknown type → dropped+warn
    const { actions } = scan(["```json-action\n{\"action\":\"explode\"}\n```\n"]);
    expect(actions).toEqual([]);
    expect(console.warn).toHaveBeenCalled();
  });
});

describe("validateActionShape (executor gate, ticket 07)", () => {
  it("accepts a scrollTo with sectionId or selector", () => {
    expect(validateActionShape({ action: "scrollTo", sectionId: "pricing" })).toBe(true);
    expect(validateActionShape({ action: "scrollTo", selector: "#p" })).toBe(true);
  });

  it("rejects scrollTo with no target", () => {
    expect(validateActionShape({ action: "scrollTo" })).toBe(false);
  });

  it("accepts highlight (selector required) and move (near required)", () => {
    expect(validateActionShape({ action: "highlight", selector: "#x" })).toBe(true);
    expect(validateActionShape({ action: "highlight" })).toBe(false);
    expect(validateActionShape({ action: "move", near: "pricing" })).toBe(true);
  });

  it("rejects non-objects and unknown action types", () => {
    expect(validateActionShape(null)).toBe(false);
    expect(validateActionShape("navigate")).toBe(false);
    expect(validateActionShape({ action: "say", text: "hi" })).toBe(false);
  });
});

describe("parseNavPath (same-origin guard, ticket 07)", () => {
  it("accepts same-origin absolute paths", () => {
    expect(parseNavPath("/about")).toBe("/about");
    expect(parseNavPath("/")).toBe("/");
    expect(parseNavPath("/shop?item=2#reviews")).toBe("/shop?item=2#reviews");
  });

  it("rejects protocol-relative, schemed, relative, and ../ escapes", () => {
    expect(parseNavPath("//evil.com")).toBe(null);
    expect(parseNavPath("https://evil.com")).toBe(null);
    expect(parseNavPath("about")).toBe(null);
    expect(parseNavPath("/x/../../etc")).toBe(null);
    expect(parseNavPath("/x\\y")).toBe(null);
  });
});

describe("createRateCap (8 actions / 5 s, ticket 07)", () => {
  it("allows up to 8 within the window, drops the 9th", () => {
    const cap = createRateCap();
    const now = 1_000;
    for (let i = 0; i < 8; i++) expect(cap.allow(now)).toBe(true);
    expect(cap.allow(now)).toBe(false);
  });

  it("slides: actions after the window closes are allowed again", () => {
    const cap = createRateCap();
    const t = 10_000;
    for (let i = 0; i < 8; i++) cap.allow(t);
    expect(cap.allow(t + 1)).toBe(false);
    expect(cap.allow(t + 5_001)).toBe(true);
  });
});

import type { Action } from "@shared/types";

// ─── Scanner (pure) ─────────────────────────────────────────────────────────
// Incremental json-action fence scanner (PLAN.md §3.4, tickets 04/06).
// feed(chunk) → { prose: text safe to render now, actions: newly completed }
// Only fences tagged EXACTLY `json-action` (case-sensitive) are parsed+executed;
// every other fence is ordinary prose. Malformed/unclosed → discard + warn.

const OPEN_RE = /^ {0,3}```json-action\s*$/;
const CLOSE_RE = /^ {0,3}```\s*$/;
const ALLOWED: Action["action"][] = ["scrollTo", "highlight", "navigate", "move"];

export interface ScanResult {
  prose: string;
  actions: Action[];
}

export function createActionScanner() {
  let lineBuf = ""; // partial line waiting for \n
  let inside = false; // inside a json-action fence
  let body: string[] = []; // fence body lines
  let pendingProse: string[] = []; // prose held while inside (usually empty)

  function finishLine(line: string, out: ScanResult) {
    if (!inside) {
      if (OPEN_RE.test(line)) {
        inside = true;
        body = [];
        pendingProse = [];
      } else {
        out.prose += line + "\n";
      }
      return;
    }
    if (CLOSE_RE.test(line)) {
      inside = false;
      const json = body.join("\n");
      body = [];
      out.prose += pendingProse.join(""); // held prose (none, kept for clarity)
      pendingProse = [];
      const action = parseAction(json);
      if (action) out.actions.push(action);
      return;
    }
    body.push(line);
  }

  function parseAction(json: string): Action | null {
    try {
      const obj = JSON.parse(json);
      if (validateActionShape(obj)) return obj as Action;
      console.warn("[mini-chat] dropped unknown/malformed action:", json);
      return null;
    } catch {
      console.warn("[mini-chat] dropped invalid action JSON");
      return null;
    }
  }

  return {
    feed(chunk: string): ScanResult {
      const out: ScanResult = { prose: "", actions: [] };
      lineBuf += chunk;
      let nl: number;
      while ((nl = lineBuf.indexOf("\n")) !== -1) {
        const line = lineBuf.slice(0, nl);
        lineBuf = lineBuf.slice(nl + 1);
        finishLine(line, out);
      }
      return out;
    },
    flush(): ScanResult {
      const out: ScanResult = { prose: "", actions: [] };
      if (lineBuf !== "") {
        finishLine(lineBuf, out); // unterminated final line
        lineBuf = "";
      }
      if (inside) {
        console.warn("[mini-chat] discarded unclosed action fence at end of stream");
        inside = false;
        body = [];
      }
      return out;
    },
  };
}

// ─── Pure gates (executor policy, ticket 07) ────────────────────────────────

export function validateActionShape(v: unknown): boolean {
  if (typeof v !== "object" || v === null) return false;
  const a = v as Record<string, unknown>;
  switch (a.action) {
    case "scrollTo":
      return typeof a.sectionId === "string" || typeof a.selector === "string";
    case "highlight":
      return typeof a.selector === "string";
    case "navigate":
      return typeof a.path === "string";
    case "move":
      return typeof a.near === "string";
    default:
      return false;
  }
}

/** Same-origin absolute path only ("/x", "/x?y#z"). Else null. */
export function parseNavPath(path: string): string | null {
  if (!path.startsWith("/")) return null;
  if (path.startsWith("//") || path.includes("\\") || path.includes("://")) return null;
  if (/(^|\/)\.\.?(\/|$)/.test(path)) return null; // no . / .. segments
  return path;
}

/** Sliding-window rate cap: `limit` actions per `windowMs` (default 8/5s). */
export function createRateCap(limit = 8, windowMs = 5_000) {
  let times: number[] = [];
  return {
    allow(now: number): boolean {
      times = times.filter((t) => now - t < windowMs);
      if (times.length >= limit) return false;
      times.push(now);
      return true;
    },
  };
}

// ─── DOM executor (thin; policy above is pure) ──────────────────────────────

const FORBIDDEN_TAGS = new Set([
  "SCRIPT", "STYLE", "HEAD", "TITLE", "META", "LINK", "TEMPLATE", "NOSCRIPT",
]);

export interface ExecutorOptions {
  enabled: () => boolean; // action toggle (persisted pref, default ON)
  onNavigate: (path: string) => Promise<boolean>; // one-tap confirm; true = go
  onGaze: (target: { x: number; y: number } | null) => void; // orb eye target
  onMove: (near: string) => void; // delegate to the movement engine
}

/** Resolve a target element: unique match, outside our shadow root, allowed tag. */
function resolveTarget(
  ref: { sectionId?: string; selector?: string },
  widgetRoot: ShadowRoot,
  doc: Document,
): HTMLElement | null {
  let els: NodeListOf<Element>;
  if (ref.sectionId) els = doc.querySelectorAll(`[id="${cssEscape(ref.sectionId)}"]`);
  else if (ref.selector) els = doc.querySelectorAll(ref.selector);
  else return null;
  if (els.length !== 1) return null;
  const el = els[0] as HTMLElement;
  if (!(el instanceof HTMLElement)) return null;
  if (widgetRoot.contains(el)) return null; // never act on ourselves
  if (FORBIDDEN_TAGS.has(el.tagName)) return null;
  return el;
}

function cssEscape(s: string): string {
  return (window.CSS && CSS.escape) ? CSS.escape(s) : s.replace(/["\\]/g, "\\$&");
}

export function createExecutor(widgetRoot: ShadowRoot, opts: ExecutorOptions) {
  const cap = createRateCap();
  let rateWarned = false;

  async function execute(action: Action) {
    if (!opts.enabled()) return; // toggle OFF → silent no-op
    if (!cap.allow(Date.now())) {
      if (!rateWarned) {
        console.warn("[mini-chat] action rate cap exceeded — dropping");
        rateWarned = true;
      }
      return;
    }
    switch (action.action) {
      case "scrollTo": {
        const el = resolveTarget(action, widgetRoot, document);
        if (!el) return warnDrop(action);
        gaze(el);
        el.scrollIntoView({ behavior: "smooth", block: "center" });
        return;
      }
      case "highlight": {
        const el = resolveTarget(action, widgetRoot, document);
        if (!el) return warnDrop(action);
        gaze(el);
        el.setAttribute("data-mini-highlight", "");
        setTimeout(
          () => el.removeAttribute("data-mini-highlight"),
          action.durationMs ?? 2_000,
        );
        return;
      }
      case "navigate": {
        const path = parseNavPath(action.path);
        if (!path) return warnDrop(action);
        const ok = await opts.onNavigate(path);
        if (ok) window.location.assign(path);
        return;
      }
      case "move": {
        opts.onMove(action.near); // movement engine resolves + clamps
        const el = tryResolveNear(action.near);
        if (el) gaze(el);
        return;
      }
    }
  }

  function tryResolveNear(near: string): HTMLElement | null {
    const m = near.match(/^(\d+),(\d+)$/); // "x,y" coords — orb itself gazes there
    if (m) return null;
    if (["top-left", "top-right", "bottom-left", "bottom-right"].includes(near)) return null;
    const el = resolveTarget({ selector: near }, widgetRoot, document)
      ?? resolveTarget({ sectionId: near }, widgetRoot, document);
    return el;
  }

  function gaze(el: HTMLElement) {
    const r = el.getBoundingClientRect();
    opts.onGaze({ x: r.left + r.width / 2, y: r.top + r.height / 2 });
  }

  function warnDrop(action: Action) {
    console.warn("[mini-chat] action target unresolvable/forbidden — ignored:", action);
  }

  return { execute };
}

