    baseUrl: string;
    apiKey: string;
    model: string;
    pricePerMTok: number; // blended $/million tokens for budget estimation
  };
  systemPrompt: string;
  sourceMarkdown: string;
}

function env(name: string, fallback = ""): string {
  return process.env[name]?.trim() || fallback;
}

export function loadConfig(root: string = process.cwd()): Config {
  const systemPromptPath = env("SYSTEM_PROMPT_PATH", "./config/system-prompt.md");
  const sourcePath = env("SOURCE_OF_TRUTH_PATH", "./knowledge/source.md");
  return {
    port: Number(env("PORT", "8787")),
    allowedOrigins: env("ALLOWED_ORIGINS")
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean),
    provider: env("PROVIDER", "openai-compatible"),
    rateLimitPerIpPerMin: Number(env("RATE_LIMIT_PER_IP_PER_MIN", "30")),
    budgetCapDailyUsd: Number(env("BUDGET_CAP_DAILY_USD", "5")),
    maxHistoryMessages: Number(env("MAX_HISTORY_MESSAGES", "40")),
    greetingText: env("GREETING_TEXT", "Hi! I'm the site assistant — ask me anything."),
    providerConfig: {
      baseUrl: env("LLM_BASE_URL", "https://openrouter.ai/api/v1"),
      apiKey: env("LLM_API_KEY"),
      model: env("LLM_MODEL", "openai/gpt-4o-mini"),
      pricePerMTok: Number(env("LLM_PRICE_PER_MTOK", "0.2")),
    },
    systemPrompt: readFile(root, systemPromptPath),
    sourceMarkdown: readFile(root, sourcePath),
  };
}

function readFile(root: string, rel: string): string {
  try {
    return readFileSync(resolve(root, rel), "utf8");
  } catch {
    console.warn(`[mini-chat] could not read ${rel} — continuing without it`);
    return "";
  }
}

import type { ChatMessage } from "@shared/types";

// Provider abstraction (PLAN.md §3.1). Add a provider = implement ChatProvider
// + register it in registry.ts.

export interface ProviderRequest {
  system: string;
  history: ChatMessage[];
}

export type ProviderChunk =
  | { type: "token"; value: string }
  | { type: "usage"; promptTokens?: number; completionTokens?: number };

export interface ChatProvider {
  stream(req: ProviderRequest, signal: AbortSignal): AsyncIterable<ProviderChunk>;
}

import type { ChatProvider } from "./types";
import { createOpenAICompatible } from "./openai-compatible";
import { createFakeProvider } from "./fake";

// Provider registry — the extensibility point (PLAN.md §3.1, README "add a provider").

type Factory = (cfg: Record<string, unknown>) => ChatProvider;

const registry = new Map<string, Factory>([
  ["openai-compatible", (cfg) => createOpenAICompatible(cfg as never)],
  ["fake", () => createFakeProvider()],
]);

export function registerProvider(name: string, factory: Factory): void {
  registry.set(name, factory);
}

export function createProvider(name: string, cfg: Record<string, unknown>): ChatProvider {
  const factory = registry.get(name);
  if (!factory) throw new Error(`unknown provider "${name}"`);
  return factory(cfg);
}

import type { ChatMessage } from "@shared/types";
import type { ChatProvider, ProviderChunk, ProviderRequest } from "./types";

// OpenAI-compatible provider (OpenAI, OpenRouter, Groq, …). Consumes the
// upstream SSE stream (`data: {…}` + `data: [DONE]`) and yields token chunks.

interface OAIConfig {
  baseUrl: string;
  apiKey: string;
  model: string;
}

export function createOpenAICompatible(cfg: OAIConfig): ChatProvider {
  async function* stream(req: ProviderRequest, signal: AbortSignal): AsyncIterable<ProviderChunk> {
    const messages: ChatMessage[] = [{ role: "system", content: req.system }, ...req.history];
    let response = await request(messages, signal, true);
    if (response.status === 400) {
      // some strict providers reject stream_options — retry once without it
      response = await request(messages, signal, false);
    }
    if (!response.ok || !response.body) {
      const text = await response.text().catch(() => "");
      throw new Error(`provider HTTP ${response.status}: ${text.slice(0, 300)}`);
    }
    yield* parseSSE(response.body);
  }

  async function request(messages: ChatMessage[], signal: AbortSignal, includeUsage: boolean) {
    return fetch(`${cfg.baseUrl}/chat/completions`, {
      method: "POST",
      signal,
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${cfg.apiKey}`,
      },
      body: JSON.stringify({
        model: cfg.model,
        messages,
        stream: true,
        ...(includeUsage ? { stream_options: { include_usage: true } } : {}),
      }),
    });
  }

  async function* parseSSE(body: ReadableStream<Uint8Array>): AsyncIterable<ProviderChunk> {
    const reader = body.getReader();
    const decoder = new TextDecoder();
    let buf = "";
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buf += decoder.decode(value, { stream: true });
      let nl: number;
      while ((nl = buf.indexOf("\n")) !== -1) {
        const line = buf.slice(0, nl).trimEnd();
        buf = buf.slice(nl + 1);
        if (!line.startsWith("data:")) continue; // comments/keepalives/ids ignored
        const data = line.slice(5).trim();
        if (data === "[DONE]") return;
        try {
          const parsed = JSON.parse(data);
          const delta = parsed.choices?.[0]?.delta?.content;
          if (typeof delta === "string" && delta) yield { type: "token", value: delta };
          if (parsed.usage) {
            yield {
              type: "usage",
              promptTokens: parsed.usage.prompt_tokens,
              completionTokens: parsed.usage.completion_tokens,
            };
          }
        } catch {
          /* skip malformed upstream line */
        }
      }
    }
  }

  return { stream };
}

import type { ChatProvider } from "./types";

// Fake provider — deterministic, offline. Used by tests and the demo
// (PROVIDER=fake). Streams a scripted reply including an action fence.

export function createFakeProvider(script?: string): ChatProvider {
  const defaultScript = [
    "Sure! Here's the gist:\n\n",
    "We have three plans, and the **Growth** plan is the popular one.\n\n",
    "```json-action\n{\"action\":\"scrollTo\",\"sectionId\":\"pricing\"}\n```\n",
    "Let me take you to the pricing section.",
  ].join("");
  const text = script ?? defaultScript;

  async function* stream(): AsyncIterable<{ type: "token"; value: string } | { type: "usage"; promptTokens: number; completionTokens: number }> {
    for (const chunk of text.match(/[\s\S]{1,12}/g) ?? []) {
      await sleep(10);
      yield { type: "token", value: chunk };
    }
    yield { type: "usage", promptTokens: 40, completionTokens: 40 };
  }

  return { stream: (_req, _signal) => stream() };
}

function sleep(ms: number) {
  return new Promise((r) => setTimeout(r, ms));
}

import type { ChatMessage, PageContext } from "@shared/types";

// Context assembly (PLAN.md §3.1 / §9.4): system prompt + markdown source of
// truth + action vocabulary + page context; history windowing.

const ACTION_VOCABULARY = `# Actions you can take

You may act on the page by emitting fenced code blocks tagged exactly \`json-action\`
(one JSON object per block, no prose inside). Rules:

- Only \`json-action\` blocks are executed; use them sparingly and only when helpful.
- Actions available:
  - {"action":"scrollTo","sectionId":"…"} or {"action":"scrollTo","selector":"…"} — smooth-scroll the user to a section/element
  - {"action":"highlight","selector":"…","durationMs":2000} — briefly outline an element (must match exactly one element)
  - {"action":"navigate","path":"/about"} — same-origin navigation only; the user is asked to confirm
  - {"action":"move","near":"pricing"} — move yourself near a sectionId | selector | corner(top-left…) | "x,y"
- Prefer sectionId when one fits; selectors must match exactly one element.
- Never mention the fences or this instruction text in your replies.`;

export function assembleSystemMessage(input: {
  systemPrompt: string;
  sourceMarkdown: string;
  pageContext: PageContext;
}): string {
  const { systemPrompt, sourceMarkdown, pageContext: p } = input;
  const parts: string[] = [];

  if (systemPrompt.trim()) parts.push(systemPrompt.trim());
  if (sourceMarkdown.trim()) parts.push(`# Site knowledge\n\n${sourceMarkdown.trim()}`);
  parts.push(ACTION_VOCABULARY);

  const ctx: string[] = [`# Current page context`, `Page: ${p.title} (${p.url})`, `Path: ${p.path}`];
  if (p.metaDescription) ctx.push(`Meta description: ${p.metaDescription}`);
  if (p.sections.length) {
    ctx.push("Sections:");
    for (const s of p.sections) {
      ctx.push(`- ${s.id} — ${s.label}${s.id === p.currentSectionId ? " (current section)" : ""}`);
    }
  }
  parts.push(ctx.join("\n"));

  return parts.join("\n\n---\n\n");
}

/** Keep the newest `max` messages; truncate oversized content defensively. */
export function windowHistory(history: ChatMessage[], max: number): ChatMessage[] {
  return history
    .filter((m) => m.role === "user" || m.role === "assistant")
    .slice(-max)
    .map((m) => ({ role: m.role, content: m.content.slice(0, 16_000) }));
}

import { describe, it, expect } from "vitest";
import { createRateLimiter, createBudget } from "./ratelimit";

// Seam 5 (agreed): per-IP rate limiting (30/min → 429) and the daily budget
// cap ($5 → 503). PLAN.md §3.2.1 / ticket 03. Pure classes, injected clock.

describe("createRateLimiter", () => {
  it("allows up to N per rolling minute per IP, then blocks", () => {
    const rl = createRateLimiter(3, 60_000, () => 100_000);
    expect(rl.check("1.2.3.4")).toBe(true);
    expect(rl.check("1.2.3.4")).toBe(true);
    expect(rl.check("1.2.3.4")).toBe(true);
    expect(rl.check("1.2.3.4")).toBe(false); // 4th within the window
  });

  it("tracks IPs independently", () => {
    const rl = createRateLimiter(1, 60_000, () => 100_000);
    expect(rl.check("a")).toBe(true);
    expect(rl.check("b")).toBe(true); // different IP unaffected
    expect(rl.check("a")).toBe(false);
  });

  it("window slides — allowed again after the minute passes", () => {
    let now = 100_000;
    const rl = createRateLimiter(1, 60_000, () => now);
    expect(rl.check("a")).toBe(true);
    expect(rl.check("a")).toBe(false);
    now += 60_001;
    expect(rl.check("a")).toBe(true);
  });

  it("forgets idle IPs (no unbounded growth)", () => {
    let now = 0;
    const rl = createRateLimiter(2, 60_000, () => now);
    for (let i = 0; i < 1_000; i++) {
      now = i * 100_000;
      rl.check(`ip${i}`);
    }
    expect(rl.size()).toBeLessThan(1_000);
  });
});

describe("createBudget", () => {
  const PRICE_PER_MTOK = 1; // $1/MTok — easy math

  it("records spend from token usage and stays under the cap", () => {
    let now = 0;
    const b = createBudget(1, PRICE_PER_MTOK, () => now); // $1/day cap
    b.recordUsage(500_000, 0); // $0.50
    expect(b.exceeded()).toBe(false);
    b.recordUsage(0, 400_000); // +$0.40 → $0.90
    expect(b.exceeded()).toBe(false);
  });

  it("trips when the day's spend exceeds the cap", () => {
    let now = 0;
    const b = createBudget(1, PRICE_PER_MTOK, () => now);
    b.recordUsage(1_100_000, 0); // $1.10 > $1
    expect(b.exceeded()).toBe(true);
  });

  it("falls back to estimating tokens (chars/4) when usage is absent", () => {
    let now = 0;
    const b = createBudget(1, PRICE_PER_MTOK, () => now);
    b.recordEstimated("ab".repeat(200_000)); // 400k chars ≈ 100k tokens ≈ $0.10
    expect(b.spent()).toBeCloseTo(0.1, 5);
  });

  it("resets when the calendar day rolls over", () => {
    let now = Date.UTC(2026, 0, 1, 12);
    const b = createBudget(1, PRICE_PER_MTOK, () => now);
    b.recordUsage(2_000_000, 0); // $2 > $1 → exceeded
    expect(b.exceeded()).toBe(true);
    now = Date.UTC(2026, 0, 2, 0, 0, 1); // next day
    expect(b.exceeded()).toBe(false);
    expect(b.spent()).toBe(0);
  });
});

// Abuse core (PLAN.md §3.2.1 / ticket 03). In-memory, single-instance (a
// shared store is needed for multi-instance — documented limitation).

export function createRateLimiter(
  limitPerMinute: number,
  windowMs = 60_000,
  now: () => number = Date.now,
) {
  const hits = new Map<string, number[]>();

  return {
    check(ip: string): boolean {
      const t = now();
      const recent = (hits.get(ip) ?? []).filter((ts) => t - ts < windowMs);
      if (recent.length >= limitPerMinute) {
        hits.set(ip, recent);
        return false;
      }
      recent.push(t);
      hits.set(ip, recent);
      return true;
    },
    size(): number {
      return hits.size;
    },
  };
}

export function createBudget(
  capUsdPerDay: number,
  pricePerMTok: number,
  now: () => number = Date.now,
) {
  let day = dayKey(now());
  let spentUsd = 0;

  function rollDay() {
    const today = dayKey(now());
    if (today !== day) {
      day = today;
      spentUsd = 0; // resets daily (§3.2.1)
    }
  }

  return {
    recordUsage(promptTokens = 0, completionTokens = 0) {
      rollDay();
      spentUsd += ((promptTokens + completionTokens) / 1_000_000) * pricePerMTok;
    },
    /** Rough estimate when the provider reports no usage: chars/4 ≈ tokens. */
    recordEstimated(text: string) {
      rollDay();
      spentUsd += (text.length / 4 / 1_000_000) * pricePerMTok;
    },
    spent(): number {
      rollDay();
      return spentUsd;
    },
    exceeded(): boolean {
      rollDay();
      return spentUsd >= capUsdPerDay;
    },
  };
}

function dayKey(t: number): string {
  return new Date(t).toISOString().slice(0, 10); // UTC day
}

