import { useCallback, useEffect, useRef, useState } from "react";
import type { ChatMessage, ExpressionState, PageContext, ServerEvent, StoredSession } from "@shared/types";
import { createActionScanner } from "./actions";
import type { Action } from "@shared/types";
import type { Memory } from "./storage";

// The chat hook (PLAN.md §3.1 `useChat`): SSE client, history, persist,
// expression state, action dispatch, §3.8 error UX. Manual/browser-verified.

export type ErrorKind = "rate" | "budget" | "network" | "stream";

export interface ChatError {
  kind: ErrorKind;
  message: string;
  retry?: () => void;
}

export interface UseChatOptions {
  backendUrl: string;
  agentId: string;
  memory: Memory;
  getPageContext: () => PageContext;
  onAction: (action: Action) => void;
  onExpression?: (expr: ExpressionState) => void;
}

const WATCHDOG_MS = 35_000; // §3.2.2 — silence mid-turn → redial
const DONE_SETTLE_MS = 1_600;

export function useChat(opts: UseChatOptions) {
  const { backendUrl, agentId, memory, getPageContext, onAction } = opts;

  const [history, setHistory] = useState<ChatMessage[]>(() => memory.load()?.history ?? []);
  const [streamText, setStreamText] = useState("");
  const [phase, setPhase] = useState<ExpressionState>("idle");
  const [error, setError] = useState<ChatError | null>(null);
  const [inputDisabled, setInputDisabled] = useState(false);
  const [reconnecting, setReconnecting] = useState(false);

  const sessionRef = useRef<StoredSession | null>(null);
  const esRef = useRef<EventSource | null>(null);
  const scannerRef = useRef(createActionScanner());
  const lastEventAt = useRef(Date.now());
  const lastAttempt = useRef<{ before: ChatMessage[]; user: ChatMessage } | null>(null);
  const settleTimer = useRef<ReturnType<typeof setTimeout>>();

  if (!sessionRef.current) {
    const loaded = memory.load();
    sessionRef.current = loaded ?? {
      sessionId: newId(),
      createdAt: Date.now(),
      history: [],
      prefs: {},
    };
    memory.save(sessionRef.current);
  }

  useEffect(() => {
    opts.onExpression?.(phase);
  }, [phase]); // eslint-disable-line react-hooks/exhaustive-deps

  const persist = useCallback(
    (h: ChatMessage[]) => {
      if (!sessionRef.current) return;
      sessionRef.current = { ...sessionRef.current, history: h };
      memory.save(sessionRef.current);
      setHistory(h);
    },
    [memory],
  );

  // ── SSE lifecycle (§3.2.2) ────────────────────────────────────────────────

  const connect = useCallback((sessionId: string) => {
    esRef.current?.close();
    const es = new EventSource(`${backendUrl}/api/sse?sessionId=${encodeURIComponent(sessionId)}`);
    esRef.current = es;

    es.onopen = () => setReconnecting(false);
    es.onerror = () => setReconnecting(true); // native auto-reconnect handles it
    es.onmessage = (ev) => {
      lastEventAt.current = Date.now();
      let event: ServerEvent;
      try {
        event = JSON.parse(ev.data);
      } catch {
        return;
      }
      if (event.type === "token") {
        setPhase((p) => (p === "thinking" ? "speaking" : p));
        const out = scannerRef.current.feed(event.value);
        for (const a of out.actions) onAction(a);
        if (out.prose) setStreamText((t) => t + out.prose);
      }
      // 'done' and 'error' are handled by the send() promise path via a queue —
      // simplest: track completion here.
      if (event.type === "done") finishTurn();
      if (event.type === "error") {
        setStreamText((t) => {
          if (t) {
            // keep the partial reply, mark it, allow retry (§3.8)
            persist([...currentHistory(), { role: "assistant", content: t }]);
          }
          return t;
        });
        setError({ kind: "stream", message: "Something went wrong finishing that.", retry: retryLast });
        setPhase("idle");
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [backendUrl, onAction]);

  function currentHistory(): ChatMessage[] {
    return sessionRef.current?.history ?? [];
  }

  function finishTurn() {
    const fin = scannerRef.current.flush();
    for (const a of fin.actions) onAction(a);
    setStreamText((t) => {
      const finalText = (t + fin.prose).trim();
      if (finalText) persist([...currentHistory(), { role: "assistant", content: finalText }]);
      return "";
    });
    setPhase("done");
    clearTimeout(settleTimer.current);
    settleTimer.current = setTimeout(() => setPhase("idle"), DONE_SETTLE_MS);
    lastAttempt.current = null;
  }

  function retryLast() {
    const attempt = lastAttempt.current;
    if (!attempt) return;
    persist([...attempt.before, attempt.user]);
    runTurn(attempt.before, attempt.user);
  }

  // ── watchdog: silence DURING a turn → redial (§3.2.2) ────────────────────

  useEffect(() => {
    const iv = setInterval(() => {
      if ((phase === "thinking" || phase === "speaking") && Date.now() - lastEventAt.current > WATCHDOG_MS) {
        esRef.current?.close();
        if (sessionRef.current) connect(sessionRef.current.sessionId);
        setReconnecting(true);
      }
    }, 5_000);
    return () => clearInterval(iv);
  }, [phase, connect]);

  useEffect(() => {
    connect(sessionRef.current!.sessionId);
    return () => esRef.current?.close();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ── send (§3.8 error mapping) ────────────────────────────────────────────

  const runTurn = useCallback(
    async (before: ChatMessage[], userMsg: ChatMessage) => {
      setError(null);
      setPhase("thinking");
      lastEventAt.current = Date.now();
      scannerRef.current = createActionScanner();
      try {
        const res = await fetch(`${backendUrl}/api/chat`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            sessionId: sessionRef.current!.sessionId,
            agentId,
            history: [...before, userMsg],
            pageContext: getPageContext(),
          }),
        });
        if (res.status === 429) {
          setError({ kind: "rate", message: "Slow down a sec — try again in a moment." });
          setPhase("idle");
          return;
        }
        if (res.status === 503) {
          setError({ kind: "budget", message: "The assistant is taking a break for today." });
          setInputDisabled(true); // the only case that disables input (§3.8)
          setPhase("idle");
          return;
        }
        if (!res.ok) throw new Error(String(res.status));
        // tokens stream in via SSE; done/error finalize there
      } catch {
        setError({
          kind: "network",
          message: "Can't reach the assistant — check your connection.",
          retry: () => {
            persist([...before, userMsg]);
            runTurn(before, userMsg);
          },
        });
        setPhase("idle");
      }
    },
    [agentId, backendUrl, getPageContext, persist],
  );

  const send = useCallback(
    (text: string) => {
      const userMsg: ChatMessage = { role: "user", content: text.trim() };
      if (!userMsg.content) return;
      const before = currentHistory();
      lastAttempt.current = { before, user: userMsg };
      persist([...before, userMsg]);
      void runTurn(before, userMsg);
    },
    [persist, runTurn],
  );

  const clearChat = useCallback(() => {
    clearTimeout(settleTimer.current);
    const fresh = memory.clearChat();
    sessionRef.current = fresh;
    setHistory([]);
    setStreamText("");
    setPhase("idle");
    setError(null);
    connect(fresh.sessionId); // rotated sessionId → fresh stream (§3.2.2)
  }, [connect, memory]);

  return {
    history,
    streamText,
    phase,
    error,
    inputDisabled,
    reconnecting,
    send,
    clearChat,
    dismissError: () => setError(null),
    /** External history sync (storage event from another tab, §3.6). */
    syncFromStorage: () => {
      if (phase === "thinking" || phase === "speaking") return; // don't clobber a live turn
      const loaded = memory.load();
      if (loaded) {
        sessionRef.current = loaded;
        setHistory(loaded.history);
      }
    },
  };
}

function newId(): string {
  return typeof crypto !== "undefined" && "randomUUID" in crypto
    ? crypto.randomUUID()
    : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

import { useEffect, useRef, useState } from "react";
import type { ExpressionState } from "@shared/types";

// The orb (PLAN.md §3.5, ticket 11): 4-state lifecycle + a separate gaze axis.
// Expression logic lifted from the validated prototype (prototypes/orb.html).

export interface GazeTarget {
  x: number;
  y: number;
}

const MOUTHS: Record<Exclude<ExpressionState, "speaking">, string> = {
  idle: "M25 42 Q32 46 39 42",
  thinking: "M26 43 Q32 43.5 38 43",
  done: "M24 41 Q32 48 40 41",
};

const SPEAK_MOUTHS = [
  "M27 43 Q32 45 37 43",
  "M27 42 Q32 48 37 42",
  "M27 43 Q32 46.5 37 43",
  "M27 42 Q32 49 37 42",
];

export function Orb(props: {
  expr: ExpressionState;
  gaze: GazeTarget | null;
  size?: number;
}) {
  const { expr, gaze, size = 64 } = props;
  const [mouth, setMouth] = useState(MOUTHS.idle);
  const rootRef = useRef<HTMLDivElement>(null);
  const [center, setCenter] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const measure = () => {
      const r = el.getBoundingClientRect();
      setCenter({ x: r.left + r.width / 2, y: r.top + r.height / 2 });
    };
    measure();
    const iv = setInterval(measure, 500); // cheap: gaze needs our viewport pos
    return () => clearInterval(iv);
  }, []);

  useEffect(() => {
    if (expr !== "speaking") {
      setMouth(MOUTHS[expr]);
      return;
    }
    let i = 0;
    const iv = setInterval(() => setMouth(SPEAK_MOUTHS[i++ % SPEAK_MOUTHS.length]), 120);
    return () => clearInterval(iv);
  }, [expr]);

  // gaze axis: pupils translate toward the target, clamped to the socket.
  // thinking with no target → the curious up-left glance.
  let ox = 0;
  let oy = 0;
  if (gaze) {
    const dx = gaze.x - center.x;
    const dy = gaze.y - center.y;
    const d = Math.hypot(dx, dy) || 1;
    ox = (dx / d) * 3.2;
    oy = (dy / d) * 3.2;
  } else if (expr === "thinking") {
    ox = -1.6;
    oy = -2.2;
  }

  return (
    <div ref={rootRef} style={{ width: size, height: size }}>
      <svg viewBox="0 0 64 64" width="100%" height="100%" aria-hidden="true">
        <circle
          cx="32"
          cy="32"
          r="30"
          fill={expr === "thinking" ? "#8a5cf6" : "var(--mc-accent, #6d28d9)"}
        />
        <ellipse cx="24" cy="29" rx="7" ry="8" fill="#fff" />
        <ellipse cx="40" cy="29" rx="7" ry="8" fill="#fff" />
        <circle cx="24" cy="30" r="3.4" fill="#1c1b22" transform={`translate(${ox} ${oy})`} />
        <circle cx="40" cy="30" r="3.4" fill="#1c1b22" transform={`translate(${ox} ${oy})`} />
        <path
          d={mouth}
          stroke="#1c1b22"
          strokeWidth="2.4"
          fill="none"
          strokeLinecap="round"
          style={{ transition: "d .12s" }}
        />
      </svg>
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";
import type { Prefs } from "@shared/types";

// Movement engine (PLAN.md §3.5, ticket 11): glide on an outer transform,
// idle bob on an inner element, viewport clamping, user drag with a 4px
// drag-vs-click threshold. Pure math lifted from the validated prototype.

const MARGIN = 14;
const DRAG_THRESHOLD = 4;

export interface Pos {
  x: number;
  y: number;
}

export function clampToViewport(pos: Pos, vw = innerWidth, vh = innerHeight): Pos {
  return {
    x: Math.max(MARGIN, Math.min(pos.x, vw - orbSize() - MARGIN)),
    y: Math.max(MARGIN, Math.min(pos.y, vh - orbSize() - MARGIN)),
  };
}

function orbSize(): number {
  return 64;
}

function cornerPos(corner: string): Pos {
  const vw = innerWidth;
  const vh = innerHeight;
  const s = orbSize();
  const base: Record<string, Pos> = {
    "top-left": { x: MARGIN, y: MARGIN },
    "top-right": { x: vw - s - MARGIN, y: MARGIN },
    "bottom-left": { x: MARGIN, y: vh - s - MARGIN },
    "bottom-right": { x: vw - s - MARGIN, y: vh - s - MARGIN },
  };
  return base[corner] ?? base["bottom-right"];
}

/** Adjacent, not overlapping: below if there's room, else above. */
export function adjacentTo(rect: DOMRect): Pos {
  const s = orbSize();
  const belowFits = rect.bottom + MARGIN + s <= innerHeight - MARGIN;
  return clampToViewport({
    x: rect.left + rect.width / 2 - s / 2,
    y: belowFits ? rect.bottom + MARGIN : rect.top - s - MARGIN,
  });
}

export function resolveNear(near: string): Pos {
  const coords = near.match(/^(\d+),(\d+)$/);
  if (coords) return clampToViewport({ x: Number(coords[1]), y: Number(coords[2]) });
  if (["top-left", "top-right", "bottom-left", "bottom-right"].includes(near)) {
    return cornerPos(near);
  }
  const el =
    document.getElementById(near) ??
    document.querySelector(near); // treat as selector (guarded upstream)
  if (el) return adjacentTo(el.getBoundingClientRect());
  return cornerPos("bottom-right");
}

export interface MovementOptions {
  initialHome?: Prefs["position"];
  onHomeChange: (home: Pos) => void; // persists the position pref (§3.6)
  reducedMotion: boolean;
}

export function useMovement(opts: MovementOptions) {
  const homeRef = useRef<Pos>(
    typeof opts.initialHome === "object" && opts.initialHome
      ? clampToViewport(opts.initialHome)
      : cornerPos("bottom-right"),
  );
  const [pos, setPos] = useState<Pos>(homeRef.current);
  const [dragging, setDragging] = useState(false);
  const [bobbing, setBobbing] = useState(true);
  const dragRef = useRef<{ sx: number; sy: number; pos0: Pos; moved: number; acted: boolean } | null>(null);

  // re-clamp on resize / orientation change
  useEffect(() => {
    const onResize = () => {
      homeRef.current = clampToViewport(homeRef.current);
      setPos((p) => clampToViewport(p));
    };
    addEventListener("resize", onResize);
    return () => removeEventListener("resize", onResize);
  }, []);

  const glideTo = useCallback(
    (p: Pos) => {
      setPos(clampToViewport(p));
    },
    [],
  );

  const moveNear = useCallback((near: string) => {
    setPos(resolveNear(near)); // temporary — home unchanged (ticket 11)
  }, []);

  const goHome = useCallback(() => {
    setPos(homeRef.current);
  }, []);

  // pointer handlers: <4px = click (caller opens panel), ≥4px = drag (moves home)
  const onPointerDown = useCallback((e: React.PointerEvent) => {
    dragRef.current = { sx: e.clientX, sy: e.clientY, pos0: posRef.current, moved: 0, acted: false };
    (e.target as Element).setPointerCapture?.(e.pointerId);
  }, []);

  const posRef = useRef(pos);
  posRef.current = pos;

  const onPointerMove = useCallback(
    (e: React.PointerEvent) => {
      const d = dragRef.current;
      if (!d) return;
      const dx = e.clientX - d.sx;
      const dy = e.clientY - d.sy;
      d.moved = Math.max(d.moved, Math.hypot(dx, dy));
      if (d.moved >= DRAG_THRESHOLD) {
        d.acted = true;
        setDragging(true);
        setPos(clampToViewport({ x: d.pos0.x + dx, y: d.pos0.y + dy }));
      }
    },
    [],
  );

  const onPointerUp = useCallback(
    (e: React.PointerEvent): "click" | "drag" | null => {
      const d = dragRef.current;
      dragRef.current = null;
      setDragging(false);
      if (!d) return null;
      if (!d.acted) return "click"; // under threshold → it was a click
      const p = clampToViewport(posRef.current);
      homeRef.current = p; // the user's dragged spot becomes home (§3.5)
      opts.onHomeChange(p);
      return "drag";
    },
    [opts], // eslint-disable-line react-hooks/exhaustive-deps
  );

  return {
    pos,
    dragging,
    bobbing: bobbing && !dragging,
    glideTo,
    moveNear,
    goHome,
    onPointerDown,
    onPointerMove,
    onPointerUp,
    setBobbing,
  };
}

export function isDrag(deltaPx: number): boolean {
  return Math.abs(deltaPx) >= DRAG_THRESHOLD;
}

import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import rehypeSanitize, { defaultSchema } from "rehype-sanitize";
import type { ChatMessage } from "@shared/types";
import type { ChatError } from "./useChat";

// Panel UI (PLAN.md §3.7/§3.8): safe markdown, streaming bubble, error UX,
// navigate-confirm bar, action toggle. All inside the Shadow DOM.

const sanitizeSchema = {
  ...defaultSchema,
  protocols: {
    ...defaultSchema.protocols,
    href: [...(defaultSchema.protocols?.href ?? []), "tel"], // http/https/mailto defaults + tel
  },
};

function Markdown({ children }: { children: string }) {
  return (
    <div className="mc-md">
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        rehypePlugins={[[rehypeSanitize, sanitizeSchema]]}
        components={{
          a: (props) => <a {...props} target="_blank" rel="noopener noreferrer" />,
        }}
      >
        {children}
      </ReactMarkdown>
    </div>
  );
}

export function ChatPanel(props: {
  title: string;
  greetingText: string;
  history: ChatMessage[];
  streamText: string;
  error: ChatError | null;
  inputDisabled: boolean;
  reconnecting: boolean;
  actionsEnabled: boolean;
  confirmNavigate: { path: string; resolve: (ok: boolean) => void } | null;
  onSend: (text: string) => void;
  onClear: () => void;
  onDismissError: () => void;
  onToggleActions: (on: boolean) => void;
  onNavigateAnswer: (ok: boolean) => void;
  onClose: () => void;
}) {
  const {
    title, greetingText, history, streamText, error, inputDisabled, reconnecting,
    actionsEnabled, confirmNavigate, onSend, onClear, onDismissError,
    onToggleActions, onNavigateAnswer, onClose,
  } = props;

  return (
    <div className="mc-panel" role="dialog" aria-label={title}>
      <header className="mc-header">
        <strong>{title}</strong>
        <div className="mc-header-actions">
          <label className="mc-toggle" title="Let the assistant act on the page">
            <input
              type="checkbox"
              checked={actionsEnabled}
              onChange={(e) => onToggleActions(e.target.checked)}
              aria-label="Allow page actions"
            />
            actions
          </label>
          <button onClick={onClear} aria-label="Clear chat">clear</button>
          <button onClick={onClose} aria-label="Close chat">×</button>
        </div>
      </header>

      <div className="mc-messages" aria-live="polite" aria-relevant="additions">
        {history.length === 0 && !streamText && (
          <div className="mc-msg mc-assistant"><Markdown>{greetingText}</Markdown></div>
        )}
        {history.map((m, i) => (
          <div key={i} className={`mc-msg ${m.role === "user" ? "mc-user" : "mc-assistant"}`}>
            <Markdown>{m.content}</Markdown>
          </div>
        ))}
        {streamText && (
          <div className="mc-msg mc-assistant mc-streaming">
            <Markdown>{streamText}</Markdown>
          </div>
        )}
      </div>

      {confirmNavigate && (
        <div className="mc-confirm" role="alertdialog" aria-label="Confirm navigation">
          <span>Assistant wants to take you to <code>{confirmNavigate.path}</code></span>
          <div>
            <button className="mc-primary" onClick={() => onNavigateAnswer(true)}>Let's go</button>
            <button onClick={() => onNavigateAnswer(false)}>Not now</button>
          </div>
        </div>
      )}

      {error && (
        <div className="mc-error" role="alert">
          <span>{error.message}</span>
          <div>
            {error.retry && <button onClick={error.retry}>Retry</button>}
            <button onClick={onDismissError} aria-label="Dismiss">×</button>
          </div>
        </div>
      )}

      {reconnecting && <div className="mc-status">reconnecting…</div>}

      <form
        className="mc-input"
        onSubmit={(e) => {
          e.preventDefault();
          const input = (e.currentTarget.elements.namedItem("m") as HTMLInputElement);
          if (input.value.trim()) {
            onSend(input.value);
            input.value = "";
          }
        }}
      >
        <input
          name="m"
          placeholder="Ask me anything…"
          disabled={inputDisabled}
          aria-label="Message"
        />
        <button type="submit" disabled={inputDisabled}>send</button>
      </form>
    </div>
  );
}

:host { all: initial; }

*, *::before, *::after { box-sizing: border-box; }

.mc-root {
  --mc-accent: #6d28d9;
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 2147483000;
  font: 15px/1.45 -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: #1c1b22;
}

/* ── orb (outer = position/glide, inner = idle bob) ── */
.mc-orb-wrap {
  position: absolute;
  pointer-events: auto;
  cursor: grab;
  transition: transform .5s cubic-bezier(.22, .61, .36, 1);
  will-change: transform;
  filter: drop-shadow(0 4px 8px rgba(0,0,0,.18));
  border-radius: 50%;
  border: none;
  padding: 0;
  background: none;
}
.mc-orb-wrap.mc-dragging { transition: none; cursor: grabbing; }
.mc-orb-bob { animation: mc-bob 3s ease-in-out infinite; }
@keyframes mc-bob { 0%,100%{ transform: translateY(0) } 50%{ transform: translateY(-5px) } }

/* ── panel ── */
.mc-panel {
  position: absolute;
  width: min(360px, calc(100vw - 28px));
  max-height: min(560px, calc(100vh - 100px));
  display: flex;
  flex-direction: column;
  background: #fff;
  border-radius: 14px;
  box-shadow: 0 12px 40px rgba(0,0,0,.22);
  overflow: hidden;
  pointer-events: auto;
  transform-origin: bottom right;
  animation: mc-pop .22s cubic-bezier(.22,.61,.36,1);
}
@keyframes mc-pop { from { opacity: 0; transform: scale(.85) } to { opacity: 1; transform: scale(1) } }

.mc-header {
  display: flex; justify-content: space-between; align-items: center;
  padding: 10px 12px;
  background: var(--mc-accent); color: #fff;
}
.mc-header strong { font-size: 14px; }
.mc-header-actions { display: flex; gap: 8px; align-items: center; }
.mc-header-actions button {
  background: rgba(255,255,255,.15); color: #fff; border: none;
  border-radius: 6px; padding: 3px 8px; cursor: pointer; font: inherit; font-size: 12px;
}
.mc-toggle { font-size: 12px; display: flex; gap: 4px; align-items: center; cursor: pointer; }

.mc-messages {
  flex: 1; overflow-y: auto; padding: 12px;
  display: flex; flex-direction: column; gap: 8px;
  background: #f7f6f3;
}
.mc-msg { padding: 8px 11px; border-radius: 12px; max-width: 92%; font-size: 14px; }
.mc-user { align-self: flex-end; background: var(--mc-accent); color: #fff; }
.mc-assistant { align-self: flex-start; background: #eceaf2; }
.mc-streaming::after { content: "▍"; animation: mc-blink 1s steps(2) infinite; }
@keyframes mc-blink { 50% { opacity: 0 } }

/* markdown */
.mc-md p { margin: 0 0 .5em; } .mc-md p:last-child { margin: 0; }
.mc-md pre {
  background: #1e1e24; color: #d4d4d4; padding: 8px 10px; border-radius: 8px;
  overflow-x: auto; font-size: 12.5px;
}
.mc-md code { font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace; font-size: .9em; }
.mc-md pre code { background: none; }
.mc-md code { background: rgba(0,0,0,.07); border-radius: 4px; padding: 1px 4px; }
.mc-user .mc-md code { background: rgba(255,255,255,.2); }
.mc-md table { border-collapse: collapse; } 
.mc-md th, .mc-md td { border: 1px solid #d9d6cf; padding: 4px 8px; font-size: 13px; }
.mc-md blockquote { margin: .4em 0; padding-left: .8em; border-left: 3px solid #d9d6cf; color: #6b6770; }

/* confirm / error / status */
.mc-confirm, .mc-error {
  display: flex; justify-content: space-between; align-items: center; gap: 8px;
  padding: 8px 12px; font-size: 13px;
}
.mc-confirm { background: #fff8e6; border-top: 1px solid #ecdcai; }
.mc-error { background: #fdecec; border-top: 1px solid #f3c1c1; }
.mc-confirm div, .mc-error div { display: flex; gap: 6px; }
.mc-confirm button, .mc-error button {
  font: inherit; font-size: 12.5px; border: 1px solid #cbb84f; background: #fff;
  border-radius: 6px; padding: 3px 10px; cursor: pointer;
}
.mc-error button { border-color: #d99; }
.mc-primary { background: var(--mc-accent) !important; color: #fff !important; border-color: var(--mc-accent) !important; }
.mc-status {
  padding: 4px 12px; font-size: 12px; color: #6b6770; background: #f1efe9;
  border-top: 1px solid #e4e1d8;
}

/* input */
.mc-input { display: flex; gap: 8px; padding: 10px; border-top: 1px solid #e4e1d8; background: #fff; }
.mc-input input {
  flex: 1; font: inherit; padding: 8px 12px; border: 1px solid #d9d6cf;
  border-radius: 20px; outline: none;
}
.mc-input input:focus { border-color: var(--mc-accent); }
.mc-input button {
  font: inherit; background: var(--mc-accent); color: #fff; border: none;
  border-radius: 20px; padding: 8px 16px; cursor: pointer;
}
.mc-input button:disabled, .mc-input input:disabled { opacity: .45; cursor: default; }

/* highlight action effect (on the host page) */
[data-mini-highlight] { outline: 3px solid #f0b429; outline-offset: 3px; transition: outline .15s; }

/* reduced motion (§3.8): skip the glide + bob */
@media (prefers-reduced-motion: reduce) {
  .mc-orb-wrap { transition: none; }
  .mc-orb-bob { animation: none; }
  .mc-panel { animation: none; }
}

import { useCallback, useEffect, useRef, useState } from "react";
import { createRoot, type Root } from "react-dom/client";
import type { Action, ExpressionState, Prefs } from "@shared/types";
import { ChatPanel } from "./chat-ui";
import { Orb } from "./orb";
import { useMovement } from "./movement";
import { createExecutor } from "./actions";
import { createPerception } from "./perception";
import { browserMemory } from "./storage";
import { useChat, type ChatError } from "./useChat";
import cssText from "./styles.css?raw";

// Widget shell (PLAN.md §3.1/§3.8/§9.12): Shadow-DOM mount, config bootstrap
// (init() → MiniChatConfig → data-* → defaults), full wiring of perception,
// memory, chat, actions, movement, expression.

export interface WidgetConfig {
  backendUrl: string;
  agentId: string;
  title: string;
  accentColor: string;
  greetingText?: string;
}

const DEFAULTS: WidgetConfig = {
  backendUrl: "",
  agentId: "default",
  title: "Assistant",
  accentColor: "#6d28d9",
};

/** Config precedence per-setting: init() → MiniChatConfig → data-* → defaults (§3.8). */
function resolveConfig(init?: Partial<WidgetConfig>, dataAttrs?: Record<string, string>): WidgetConfig {
  const fromData = dataAttrs ?? readDataAttrs();
  const globalCfg = (globalThis as { MiniChatConfig?: Partial<WidgetConfig> }).MiniChatConfig;
  const pick = (k: keyof WidgetConfig): string | undefined =>
    (init as Record<string, string | undefined>)?.[k] ?? globalCfg?.[k] ?? fromData[k] ?? undefined;
  return {
    backendUrl: pick("backendUrl") ?? DEFAULTS.backendUrl,
    agentId: pick("agentId") ?? DEFAULTS.agentId,
    title: pick("title") ?? DEFAULTS.title,
    accentColor: pick("accentColor") ?? pick("accent") ?? DEFAULTS.accentColor,
    greetingText: pick("greetingText") ?? pick("greeting"),
  };
}

function readDataAttrs(): Record<string, string> {
  const out: Record<string, string> = {};
  // captured at module load (currentScript goes null after)
  const el = (document.currentScript as HTMLScriptElement | null) ?? window.__miniChatScript;
  if (el) {
    for (const attr of el.attributes) {
      if (attr.name.startsWith("data-")) out[attr.name.slice(5).replace(/-(.)/g, (_, c) => c.toUpperCase())] = attr.value;
    }
  }
  return out;
}

declare global {
  interface Window {
    __miniChatScript?: HTMLScriptElement;
    MiniChat?: { init: typeof init };
  }
}

// ── the app ─────────────────────────────────────────────────────────────────

function App({ config, greetingText }: { config: WidgetConfig; greetingText: string }) {
  const shadowRef = useRef<ShadowRoot | null>(null);
  const [open, setOpen] = useState(false);
  const [expr, setExpr] = useState<ExpressionState>("idle");
  const [gaze, setGaze] = useState<{ x: number; y: number } | null>(null);
  const [confirmNav, setConfirmNav] = useState<{ path: string; resolve: (ok: boolean) => void } | null>(null);
  const [actionsEnabled, setActionsEnabled] = useState(true);
  const orbButtonRef = useRef<HTMLButtonElement>(null);
  const inputFocusRef = useRef<(() => void) | null>(null);

  const memory = useRef(browserMemory(config.agentId)).current;
  const perception = useRef(createPerception()).current;

  // prefs: action toggle + orb position (§3.6)
  useEffect(() => {
    const prefs = memory.load()?.prefs as Prefs | undefined;
    if (prefs?.actionsEnabled === false) setActionsEnabled(false);
  }, [memory]);

  const movement = useMovement({
    initialHome: memory.load()?.prefs.position,
    onHomeChange: (home) => {
      const s = memory.load();
      memory.save({ ...(s ?? { sessionId: "", createdAt: 0, history: [], prefs: {} }), prefs: { ...s?.prefs, position: home } });
    },
    reducedMotion: matchMedia("(prefers-reduced-motion: reduce)").matches,
  });

  // actions: move is temporary; after "done" the orb returns home (ticket 11)
  const goHomeRef = useRef(movement.goHome);
  goHomeRef.current = movement.goHome;
  useEffect(() => {
    if (expr === "done") {
      const t = setTimeout(() => goHomeRef.current(), DONE_RETURN_MS);
      return () => clearTimeout(t);
    }
  }, [expr]);

  const executor = useRef(
    createExecutor(shadowRef.current ?? dummyShadow(), {
      enabled: () => actionsEnabled,
      onNavigate: (path) =>
        new Promise<boolean>((resolve) => setConfirmNav({ path, resolve })),
      onGaze: (target) => setGaze(target),
      onMove: (near) => movement.moveNear(near),
    }),
  ).current;
  // keep the latest closures without recreating the executor
  executorRefs.current = { actionsEnabled, movement };

  const chat = useChat({
    backendUrl: config.backendUrl,
    agentId: config.agentId,
    memory,
    getPageContext: () => perception.getPageContext(),
    onAction: (a: Action) => void executor.execute(a),
    onExpression: (e) => setExpr(e),
  });

  // multi-tab history sync via the storage event (§3.6)
  useEffect(() => {
    const onStorage = (e: StorageEvent) => {
      if (e.key === `mini-chat:${config.agentId}`) chat.syncFromStorage();
    };
    addEventListener("storage", onStorage);
    return () => removeEventListener("storage", onStorage);
  }, [chat.syncFromStorage, config.agentId]); // eslint-disable-line react-hooks/exhaustive-deps

  // a11y (§3.8): focus input on open, orb on close; Esc closes
  useEffect(() => {
    if (open) inputFocusRef.current?.();
    else orbButtonRef.current?.focus();
  }, [open]);

  const onPointerUp = (e: React.PointerEvent) => {
    const result = movement.onPointerUp(e);
    if (result === "click") setOpen((o) => !o);
  };

  return (
    <div
      className="mc-root"
      ref={(el) => {
        if (el) shadowRef.current = el.getRootNode() as ShadowRoot;
      }}
      style={{ ["--mc-accent" as string]: config.accentColor }}
      onKeyDown={(e) => e.key === "Escape" && setOpen(false)}
    >
      <div
        className={`mc-orb-wrap${movement.dragging ? " mc-dragging" : ""}`}
        style={{ transform: `translate(${movement.pos.x}px, ${movement.pos.y}px)` }}
      >
        <div className={movement.bobbing ? "mc-orb-bob" : undefined}>
          <button
            ref={orbButtonRef}
            aria-label={config.title}
            aria-expanded={open}
            onPointerDown={movement.onPointerDown}
            onPointerMove={movement.onPointerMove}
            onPointerUp={onPointerUp}
            style={{ border: "none", background: "none", padding: 0, cursor: "inherit" }}
          >
            <Orb expr={expr} gaze={gaze} />
          </button>
        </div>
      </div>

      {open && (
        <div style={{ position: "absolute", inset: 0 }}>
          <div
            style={{
              position: "absolute",
              left: panelLeft(movement.pos.x),
              top: panelTop(movement.pos.y),
            }}
          >
            <ChatPanel
              title={config.title}
              greetingText={greetingText}
              history={chat.history}
              streamText={chat.streamText}
              error={chat.error}
              inputDisabled={chat.inputDisabled}
              reconnecting={chat.reconnecting}
              actionsEnabled={actionsEnabled}
              confirmNavigate={confirmNav}
              onSend={chat.send}
              onClear={chat.clearChat}
              onDismissError={chat.dismissError}
              onToggleActions={(on) => {
                setActionsEnabled(on);
                const s = memory.load();
                memory.save({ ...(s ?? { sessionId: "", createdAt: 0, history: [], prefs: {} }), prefs: { ...s?.prefs, actionsEnabled: on } });
              }}
              onNavigateAnswer={(ok) => {
                confirmNav?.resolve(ok);
                setConfirmNav(null);
              }}
              onClose={() => setOpen(false)}
              registerInputFocus={(fn) => (inputFocusRef.current = fn)}
            />
          </div>
        </div>
      )}
    </div>
  );
}

const DONE_RETURN_MS = 2_200;

const executorRefs: { current: { actionsEnabled: boolean; movement: { moveNear: (n: string) => void } } | null } = { current: null };

function dummyShadow(): ShadowRoot {
  return { contains: () => false } as unknown as ShadowRoot; // replaced once mounted
}

function panelLeft(orbX: number): string {
  const vw = innerWidth;
  return `${Math.max(14, Math.min(orbX > vw / 2 ? orbX - 374 : orbX + 78, vw - 374))}px`;
}
function panelTop(orbY: number): string {
  return `${Math.max(14, orbY - 80)}px`;
}

// ── mount / init (§9.12) ────────────────────────────────────────────────────

let mounted = false;

export function init(userConfig?: Partial<WidgetConfig>): void {
  if (mounted) return;
  const dataAttrs = readDataAttrs();
  const config = resolveConfig(userConfig, dataAttrs);
  if (!config.backendUrl) {
    console.warn("[mini-chat] no backendUrl — pass it to MiniChat.init, MiniChatConfig, or data-backend-url");
    return;
  }
  mounted = true;

  const host = document.createElement("div");
  host.id = "mini-chat-host";
  document.body.appendChild(host);
  const shadow = host.attachShadow({ mode: "open" });
  const style = document.createElement("style");
  style.textContent = cssText;
  shadow.appendChild(style);

  createRoot(shadow).render(<Boot config={config} />);
}

/** Greeting precedence: embed config → server /api/config → default (§3.2.1/§3.8). */
function Boot({ config }: { config: WidgetConfig }) {
  const [greeting, setGreeting] = useState(config.greetingText ?? "");
  useEffect(() => {
    if (config.greetingText) return; // embed config wins
    let alive = true;
    fetch(`${config.backendUrl}/api/config`)
      .then((r) => (r.ok ? r.json() : null))
      .then((cfg) => {
        if (alive && cfg?.greetingText) setGreeting(cfg.greetingText);
      })
      .catch(() => {});
    return () => {
      alive = false;
    };
  }, [config.backendUrl, config.greetingText]);
  const greetingText = greeting || "Hi! I'm the site assistant — ask me anything.";
  return <App config={config} greetingText={greetingText} />;
}

// auto-mount: script tag with config OR window.MiniChatConfig (§9.12)
window.__miniChatScript = document.currentScript as HTMLScriptElement | undefined;
window.MiniChat = { init };
if (typeof window !== "undefined") {
  const hasData = document.currentScript?.dataset.backendUrl;
  if (hasData || (globalThis as { MiniChatConfig?: unknown }).MiniChatConfig) {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", () => init());
    } else {
      init();
    }
  }
}

